use crate::account::Kind;
use crate::money::Money;
use crate::position::AccountBalance;

/// Record a balance from the figure a statement PRINTS.
///
/// The `kind` decides the sign, so this is the only place a printed number becomes a signed one.
pub fn from_printed(account: &str, as_of: &str, printed: Money, kind: Kind) -> AccountBalance {
    AccountBalance {
        account: account.to_string(),
        as_of: as_of.to_string(),
        balance: crate::position::from_statement_balance(kind, printed),
    }
}
